from caya_music import start_song, add_note
def make_phrase(notes, repeats):
    result = []
    for repeat in range(repeats):
        for note in notes:
            result.append(note)
    return result

source_notes = ["C4", "E4", "G4"]
start_song(96, "pluck", "音列を作る関数")
phrase = make_phrase(source_notes, 2)
for note in phrase:
    add_note(note, 0.5)

from caya_music import start_song, add_note, new_track
def add_phrase(notes, beat, repeats):
    for repeat in range(repeats):
        for note in notes:
            add_note(note, beat)

start_song(96, "bell", "私の8拍の作品")
add_phrase(["C4", "E4", "G4", "C5"], 0.5, 4)
new_track("bass", instrument="bass")
add_phrase(["C3", "G3"], 2, 2)
# 旋律: 4音×0.5拍×4回=8拍。低音: 2音×2拍×2回=8拍。
